(()=>{'use strict';
const G=Game,$=s=>document.querySelector(s),app=$('#app'),modal=$('#modal'),KEY='panda-neon-v1';let s=null,saved=null,drawTimer=0,cgToken=0,toastTimer,poolTimer=0,poolLoot=null;const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&(![1,2].includes(saved.schema)||!Array.isArray(saved.ledger)||!Number.isFinite(saved.balance)))saved=null;}catch{}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function save(){if(!s?.save)return;try{localStorage.setItem(KEY,JSON.stringify(s));saved=JSON.parse(JSON.stringify(s));}catch{toast('浏览器无法保存；本次仍可继续，请勿关闭页面。');}}
function call(fn){try{fn();}catch(e){toast(e.message);}}
function level(){return 1+Math.floor((s?.xp||0)/60)}
function migrateStrategies(state){if(!state)return state;const enrich=event=>{if(!event||event.strategy)return;const family=G.families.find(f=>f.title===event.title);if(family)Object.assign(event,{strategy:family.strategy,strategyName:family.strategyName,lead:family.lead});};enrich(state.event);for(const entry of state.ledger||[]){enrich(entry.event);entry.status||='settled';if(!entry.event?.strategy||state.evidence.some(e=>e.dimension==='strategy'&&e.eventId===entry.eventId))continue;const stance=entry.amount?'follow':entry.report?'study':'pass';state.evidence.push({id:'ev-'+(state.evidence.length+1),eventId:entry.eventId,family:entry.event.type,dimension:'strategy',value:entry.event.strategy+':'+stance,source:'migration',phase:'during',prompted:false,rule:G.CONFIG.rule});}state.schema=2;return state;}
const foot=()=>`<span class="mockmark">本地模拟 · 非真实行情</span>`;
function hud(){const day=s?Math.min(3,Math.floor(s.round/G.CONFIG.roundsPerDay)+1):1,turn=s?s.round%G.CONFIG.roundsPerDay+1:1;return `<header class="gamehud"><div class="goldcoin">${CityArt.icon('coin')}<b>${(s?.balance||10000).toLocaleString()}</b></div><div class="daycount">第 ${day} 天 <span>· 第 ${turn}/3 轮</span></div>${s&&(!s.tutorial||s.tutorial==='done')?'<button class="roundbutton" data-do="settings" aria-label="设置">'+CityArt.icon('gear')+'</button>':''}</header>`}
function header(){return hud()}
function world(interactive=false){if(s)GameCity.init(s);return `<div class="game-world">${CityArt.map(s,{interactive})}<div class="vignette"></div></div>`}
function character(p=G.people[0]){return `<div class="vn-character">${art(p,'large-portrait')}</div>`}
function speech(text,buttons,p=G.people[0]){return `<section class="vn-dialogue"><div class="nameplate">${p.name}<small>${p.role}</small></div><p>${text}</p><div class="vn-controls">${buttons}</div></section>`}
function dock(){return `<nav class="game-dock" aria-label="游戏操作"><button data-do="cardHall">${CityArt.icon('cards')}<span>抽卡</span></button><button data-do="warehouse">${CityArt.icon('bag')}<span>材料</span></button><button class="nextday" data-do="cycle">${CityArt.icon('clock')}<span>推进行情</span></button><button data-do="bonds">${CityArt.icon('book')}<span>伙伴</span></button><button data-do="records">${CityArt.icon('blueprint')}<span>手账</span></button></nav>`}

function art(p,cls='portrait'){return `<img class="${cls}" src="assets/${p.file}" alt="${esc(p.name)} · ${p.role}" onerror="this.hidden=true">`}
function intro(){s=null;app.innerHTML=`<main class="game opening">${world()}<div class="opening-shade"></div><div class="chapter-stamp">第一章<small>海风吹来的任命书</small></div>${character()}${speech('船快靠岸了。这里的每一块空地，都在等一个新的想法。<br>让我看看任命书……您就是新来的董事长？','<button class="primary" data-do="askName">继续 '+CityArt.icon('arrow')+'</button>')}<button class="skip-dialogue" data-do="askName">跳过对白</button>${foot()}</main>`;}
function askName(){app.innerHTML=`<main class="game opening">${world()}<div class="opening-shade"></div>${character()}<section class="vn-dialogue name-dialogue"><div class="nameplate">星澜<small>执行助理</small></div><p>请告诉我您的名字。接下来，大家统一称呼您为“董事长”。</p><form id="start"><div class="nameentry"><input id="nickname" maxlength="12" placeholder="输入你的名字" autocomplete="off" aria-label="董事长姓名"></div><label class="savechoice"><input id="persist" type="checkbox" checked> 保存到这台设备</label><small class="privacyline">名字、对话和选择只用于本局，可查看、纠正或清除。</small><button class="primary" type="submit">以董事长身份进入 →</button></form></section>${foot()}</main>`;$('#start').onsubmit=e=>{e.preventDefault();const name=$('#nickname').value.trim();if(!name)return toast('请先告诉星澜你的名字。');s=G.fresh(name,$('#persist').checked,'探索基础',10000);s.tutorial='draw';s.view='board';GameCity.init(s);save();render();};$('#nickname').focus();}

function say(text){s.chats.push({npc:s.npc,text,round:s.round});if(s.chats.length>80)s.chats.shift();save();}
function dialogue(p){const e=s.event,addr='董事长';if(!e)return `${addr}，${p.hint} 你的第一张命运卡已经送达。`;const lead=[`${addr}，先区分已知规则和未知叙事。`,`${addr}，我不会替你决定，但会守住风险边界。`,`${addr}，漂亮曲线不是证据。我们需要能复现的检验。`,`${addr}，资金的去处，必须有清晰的理由。`][s.npc];return lead+' '+p.hint;}
function render(){if(!s)return intro();GameCity.init(s);if(s.bankrupt||s.phase==='bankrupt')return bankruptcy();if(s.phase==='daybreak')return daybreak();if(s.phase==='finalReport')return finalReport();if(s.phase==='summary')return summary();if(s.view==='city')return city();const p=G.people[s.npc],last=[...s.chats].reverse().find(c=>c.npc===s.npc&&c.round===s.round),tutorial=s.tutorial&&s.tutorial!=='done',attr={trend:'趋势',value:'价值',defense:'防守',research:'研究'}[s.ledger.at(-1)?.attribute];app.innerHTML=`<main class="game event-game">${world()}${hud()}<div class="event-shade"></div>${character(p)}${!tutorial?`<button class="backcity" data-do="city">‹ 返回城市</button><div class="partner-switch">${G.people.map((p,i)=>`<button data-do="npc" data-id="${i}" class="${s.npc===i?'selected':''}" aria-label="切换到${p.name}">${art(p,'partner-face')}</button>`).join('')}</div>`:''}${eventPanel()}${speech(s.phase==='result'?`<b>${attr} +1</b><br>这次选择记下了。`:tutorial?`第一封市场来信到了。<br>${s.phase==='event'?'直接选一个。':'点卡片。'}`:(last?esc(last.text):dialogue(p)),s.phase==='result'?`<button class="primary" data-do="${tutorial?'tutorialReward':'next'}">${tutorial?'领取开城物资':s.round===G.CONFIG.rounds-1?'看最终画像':(s.round+1)%G.CONFIG.roundsPerDay===0?'结束今天':'下一轮'} →</button>`:s.phase==='ready'||s.phase==='drawing'?'':`<div class="hintrow"><button data-do="ask" data-kind="risk">问风险</button><button data-do="ask" data-kind="tech">问依据</button><button data-do="ask" data-kind="finance">问费用</button><button data-do="lesson">没听懂</button></div>${tutorial?'':`<form id="chat" class="chatrow"><input id="message" maxlength="250" aria-label="和角色讨论" placeholder="说说你的想法…"><button type="submit">发送</button></form>`}`,p)}${foot()}</main>`;if($('#chat'))$('#chat').onsubmit=e=>{e.preventDefault();call(()=>send($('#message').value));};}

function reportFor(day){const rows=s.ledger.filter(x=>Math.floor(Number(x.eventId.match(/e(\d+)$/)?.[1]||0)/3)+1===day),invested=rows.reduce((n,x)=>n+x.amount,0),fees=rows.reduce((n,x)=>n+x.fee+x.report,0),income=rows.reduce((n,x)=>n+x.credit,0),net=income-invested-fees;return {rows,invested,fees,income,net};}
function reportBody(day){const r=reportFor(day),names={full:'大笔跟进',small:'半价试买',skip:'先不买',report:'花钱调查',custom:'自定金额'};return `<div class="numbers"><div><small>投入</small><strong>${r.invested}</strong></div><div><small>收入/返还</small><strong>${r.income}</strong></div><div><small>净收入</small><strong class="${r.net>=0?'positive':'negative'}">${r.net>=0?'+':''}${r.net}</strong></div></div><p><b>费用：</b>${r.fees} 币</p><h3>董事长昨日决策</h3>${r.rows.map((x,i)=>`<div class="ledgeritem">第 ${i+1} 轮 · ${names[x.actionId]||x.actionId} · ${x.attribute} +1<br><small>投入 ${x.amount} / 返还 ${x.credit} / 净收入 ${x.delta>=0?'+':''}${x.delta}</small></div>`).join('')}`;}
function daybreak(){const day=Math.floor(s.round/G.CONFIG.roundsPerDay)+1;app.innerHTML=`<main class="game opening daybreak">${world()}<div class="opening-shade"></div>${character()}${speech(`<b>第 ${day} 天 · 昨日财报</b>${reportBody(day-1)}${s.spendingWarning?'<div class="notice">第一天投入超过初始资金 60%，后续投资按钮将变灰且不计分；仍可选择防守或研究。</div>':''}`,`<button class="primary" data-do="startDay">确认财报并进入第 ${day} 天 →</button>`)}${foot()}</main>`;save();}
function finalReport(){app.innerHTML=`<div class="shell">${header()}<main class="summary"><div class="eyebrow">第 4 天 · 最终结算</div><h1>三日经营财报</h1>${reportBody(3)}<div class="panel"><h2>三天总结果</h2><p>期初 ${s.initial.toLocaleString()} 币 → 期末 ${s.balance.toLocaleString()} 币，累计净收入 <b class="${s.balance-s.initial>=0?'positive':'negative'}">${s.balance-s.initial>=0?'+':''}${s.balance-s.initial}</b> 币。</p></div><button class="primary" data-do="finalProfile">看我的策略画像 →</button></main>${foot()}</div>`;save();}

function bankruptcy(){app.innerHTML=`<main class="bankruptcy-screen"><div class="bankruptcy-crack">⚡</div><div class="bankruptcy-card"><small>余额 ${s.balance.toLocaleString()} 币</small><h1>破产了</h1><p>钱低于 0，本局直接结束。</p><button class="primary" data-do="new">重新来一局</button><button data-do="ledger">看账本</button></div></main>`;save();}

function tradeType(action,amount,event){if(action==='report')return '研究';if(action==='skip')return '防守';if(action==='small')return '价值';return amount<=Math.floor(event.amount/2)?'价值':'趋势';}
function eventPanel(){if(s.phase==='ready'||s.phase==='drawing')return `<div class="drawstage"><button class="sealedcard ${s.phase==='drawing'?'cardspinning':''} ${s.event?'rarity-'+s.event.rarity.toLowerCase():''}" data-do="${s.phase==='drawing'?'reveal':'draw'}" aria-label="抽取事件卡"><span class="seal-border"></span><span class="seal">✦</span><b>市场来信</b><small>${s.phase==='drawing'?'点击翻开':'点击抽取'}</small></button>${s.phase==='drawing'?'<button class="cancel-draw" data-do="cancelDraw">先等等</button>':'<div class="finger-guide">点击卡片开启</div>'}</div>`;const e=s.event,day=Math.floor(s.round/G.CONFIG.roundsPerDay)+1,turn=s.round%G.CONFIG.roundsPerDay+1,fullCost=e.amount+Math.ceil(e.amount/100),smallAmount=Math.floor(e.amount/2),smallCost=smallAmount+Math.ceil(smallAmount/100);if(s.phase==='result'){const l=s.ledger.at(-1),a={trend:'趋势',value:'价值',defense:'防守',research:'研究'}[l.attribute];return `<article class="eventcard receipt"><div class="card-kicker">第 ${day} 天 · 第 ${turn}/3 轮</div><h2>${a} +1</h2><div class="receipt-value">−${l.debit}<small>今日冻结</small></div><div class="receipt-detail">预计明天返还 ${l.credit}<br>可用现金 ${s.balance}</div><button class="quiet small" data-do="ledger">看明细</button></article>`}return `<article class="eventcard card-reveal rarity-${e.rarity.toLowerCase()}"><div class="rarity-badge">${e.rarity}</div><div class="card-kicker">第 ${day} 天 · 第 ${turn}/3 轮 · 总进度 ${s.round+1}/9</div><div class="event-illustration">${CityArt.icon(e.type==='成本'?'coin':'city')}<span>${e.strategyName}</span></div><h2>${esc(e.title.split(' · ')[1]||e.title)}</h2><p>${esc(e.story)}</p><div class="notice"><b>简单说：</b>${esc(e.fact)}</div><details class="rules"><summary>钱会怎么变</summary><p>今天先冻结投入，明天返还。第三天投资在最终画像前返还。</p></details><div class="gamechoices"><button data-do="choose" data-id="full" ${s.spendingWarning||fullCost>s.balance?'disabled':''}><em class="choice-type">趋势 +1</em> 大笔跟进 <small>${s.spendingWarning?'资金纪律限制 · 不计分':fullCost>s.balance?'现金不足':e.amount+' 币 + 费用'}</small></button><button data-do="choose" data-id="small" ${s.spendingWarning||smallCost>s.balance?'disabled':''}><em class="choice-type">价值 +1</em> 半价试买 <small>${s.spendingWarning?'资金纪律限制 · 不计分':smallCost>s.balance?'现金不足':smallAmount+' 币 + 费用'}</small></button><button data-do="choose" data-id="skip"><em class="choice-type">防守 +1</em> 先不买 <small>不花钱</small></button><button data-do="choose" data-id="report" ${50>s.balance?'disabled':''}><em class="choice-type">研究 +1</em> 花钱调查 <small>${50>s.balance?'现金不足':'50 币'}</small></button></div></article>`}

function open(title,body){modal.innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="quiet small" data-do="close" aria-label="关闭">✕</button></div>${body}`;if(!modal.open)modal.showModal();}
function close(){PandaAI.cancel();clearTimeout(poolTimer);poolLoot=null;modal.close();if(s?.city)s.city.pending=null;if(s?.draft){s.draft=null;save();}cgToken++;}
modal.addEventListener('cancel',()=>{PandaAI.cancel();clearTimeout(poolTimer);poolLoot=null;if(s?.city)s.city.pending=null;if(s?.draft){s.draft=null;save();}cgToken++;});
function confirmAction(action,amount){PandaAI.cancel();s.draft=G.proposal(s,action,amount);save();const a=s.draft,e=s.event,type=tradeType(a.action,a.amount,e);open('确认选择',`<div class="trade-type"><b>${type} +1</b></div><div class="numbers"><div><small>投入</small><strong>${a.amount}</strong></div><div><small>费用</small><strong>${a.fee+a.report}</strong></div><div><small>先扣完剩下</small><strong>${s.balance-a.amount-a.fee-a.report}</strong></div></div><div class="facts">${a.amount?`赚时返还 ${Math.floor(a.amount*e.up/100)}，亏时返还 ${Math.floor(a.amount*e.down/100)}。`:a.report?'花 50 币调查，不买。':'不花钱。'}<br>余额低于 0 会直接破产。</div><label for="reason">为什么这样选（可不填）</label><textarea id="reason" maxlength="300" placeholder="写一句就行"></textarea><div class="actions" style="margin-top:15px"><button class="primary" data-do="confirm">就这么选</button><button data-do="close">返回</button></div>`)}
function ask(kind,fromPrompt=true){if(!s.event){toast('先抽取一张事件，便能针对它讨论。');return;}if(s.phase!=='event'){toast('本轮已结算；你可以查看账本，或进入下一夜。');return;}const e=s.event;G.observe(s,kind,'',fromPrompt);const response={risk:`董事长，以标准投入 ${e.amount} 计算，坏分支返还 ${Math.floor(e.amount*e.down/100)}，加上费用，净损失 ${e.amount+e.fee-Math.floor(e.amount*e.down/100)} 币。没有杠杆，本轮立即退出。你愿意为这次试验承担这个范围吗？`,tech:`董事长，这份叙事只提供合成数据。先核对样本是否独立、有没有偷看未来，以及样本外表现。游戏公开概率 ${e.p}% 只是结算设定，不是策略预测能力。`,finance:`董事长，标准试验占用 ${e.amount+e.fee} 币，占当前余额 ${((e.amount+e.fee)/s.balance*100).toFixed(1)}%。执行前可用现金剩 ${s.balance-e.amount-e.fee} 币。更小的试验也能验证想法。`};say(response[kind]);render();}
function send(t){const parsed=G.parse(s,t);if(PandaAI.enabled&&!parsed.action&&!parsed.kind){remoteDialogue(t);return;}if(parsed.action){if(s.phase!=='event')return toast('请先抽取事件。');return confirmAction(parsed.action,parsed.amount)}if(parsed.kind)return ask(parsed.kind,false);say(parsed.message);render();}
function ledger(){open('收支账本',`<p>初始 ${s.initial.toLocaleString()} 币 → 当前 ${s.balance.toLocaleString()} 币</p><small>城市周期净变化合计：${(s.city?.ledger||[]).reduce((n,l)=>n+l.delta,0)} 币；下方列出事件流水。</small><small>整数记账 · 无未平仓持仓 · 同一事件仅结算一次</small>${s.ledger.length?s.ledger.map((l,i)=>`<div class="ledgeritem"><b>${i+1}. ${esc(l.event.title)}</b><br>投入 −${l.amount} / 手续费 −${l.fee} / 报告 −${l.report} / 返还 +${l.credit}<br>${l.balanceBefore} → <b>${l.balanceAfter}</b><br><small>规则 ${l.ruleVersion} · seed ${l.event.seed} · ${l.idempotencyKey}</small><br><button class="small quiet" data-do="replay" data-id="${i}">重放核验</button></div>`).join(''):'<p class="muted">暂无已结算事件。</p>'}`)}
function bonds(){const scores={ai:0,risk:0,tech:0,finance:0},map={research:'ai',defense:'risk',trend:'tech',value:'finance'},rank=n=>n>=5?'SSR':n>=2?'SR':'R';for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(map[e.value])scores[map[e.value]]++;open('策略伙伴',`<p class="muted">同类决策和建设会增加伙伴点数：2 点升 SR，5 点升 SSR。</p><div class="partner-inventory">${G.people.map((p,i)=>{const rarity=rank(scores[p.id]);return `<button class="partner-card rarity-${rarity.toLowerCase()} ${scores[p.id]?'unlocked':'locked'}" data-do="partnerDetail" data-id="${i}"><span class="partner-rarity">${rarity}</span>${art(p,'partner-card-art')}<span class="partner-card-info"><b>${p.name}</b><small>${scores[p.id]?p.code+'经验 · '+scores[p.id]+' 点':'完成'+p.code+'决策解锁'}</small></span></button>`}).join('')}</div>`)}
function partnerDetail(i){const p=G.people[i],lines=s.chats.filter(c=>c.npc===i).slice(-3),blueprint=GameCity.blueprints.find(b=>b.partner===p.name),factor=GameCity.factors.find(f=>f.industry===blueprint?.id),score=s.evidence.filter(e=>e.dimension==='attribute'&&({ai:'research',risk:'defense',tech:'trend',finance:'value'}[p.id]===e.value)).length,rarity=score>=5?'SSR':score>=2?'SR':'R';open(p.name+' · '+rarity+'角色卡',`<div class="partner-profile">${art(p,'partner-profile-art')}<div><span class="badge">${rarity} · ${p.code}策略 · ${score} 点</span><h2>${p.name}</h2><b>${p.role}</b><p>${p.hint}</p><div class="notice"><b>玩法关联：</b>${blueprint?.name||''} → ${factor?.name||''} → 建设后增加${p.code}画像点</div><small>升级规则：2 点 SR，5 点 SSR</small></div></div><h3>最近互动</h3>${lines.map(c=>`<div class="partner-line">第 ${c.round+1} 轮 · ${esc(c.text)}</div>`).join('')||'<p class="muted">还没有互动。进入市场来信后可以和TA说话。</p>'}<button data-do="bonds">返回伙伴背包</button>`)}
const statusNames={unknown:'未观察',candidate:'候选 · 待确认',confirmed:'你已确认',rejected:'已拒绝',roleplay:'仅为角色扮演'};
function profileBody(){return `<p class="muted">只描述本局可见行为。知识与偏好不会由收益或角色好感推定。画像版本 v${s.profileVersion}。</p><label for="profileGoal">你明确选择的学习目标（可纠正）</label><select id="profileGoal">${['探索基础','验证交易想法','编程研究','工具实践'].map(g=>`<option ${g===s.goal?'selected':''}>${g}</option>`).join('')}</select><button class="small" data-do="goal">更新目标</button>${G.claims(s).map(c=>`<div class="claim"><h3>${c.label} <span class="badge">${statusNames[c.status]}</span></h3><small>观察到 ${c.events} 个场景；${c.events<2?'证据有限，不判断稳定习惯。':'跨场景出现，但仍需你确认。'}</small>${c.evidence.map(e=>`<small>${e.id} · ${e.value} · ${e.prompted?'提示后':'自主'} / ${e.phase==='after_learning'?'学习后':'学习前'}</small>`).join('')}<div class="actions" style="margin-top:10px"><button class="small" data-do="correct" data-id="${c.id}" data-value="confirmed">符合我的习惯</button><button class="small" data-do="correct" data-id="${c.id}" data-value="roleplay">只是在扮演</button><button class="small" data-do="correct" data-id="${c.id}" data-value="rejected">不符合我</button></div></div>`).join('')}<details><summary>原始资金配置证据</summary>${s.evidence.filter(x=>x.dimension==='allocation').map(x=>`<p class="muted">${esc(x.value)} · ${esc(x.eventId)}</p>`).join('')||'尚无配置行动'}</details><div class="notice">知识状态：${s.lessons.length?'已学习 '+s.lessons.join('、'):'未测，不等于低分'}。练习答对仅表示学习后完成该题，尚未验证迁移能力。</div>`}
const lessons={
'回撤':['从高点到低点的落差','若净值从 100 跌到 80，回撤为 (100−80)÷100 = 20%。回到 100 却要上涨 25%，因为新的基数是 80。','从100跌到80，要回到100需上涨多少？',['20%','25%'],1],
'样本外验证':['把考试卷藏起来','在一段历史数据上选择规则，再在未参与选择的数据上检验。反复看测试集并调整，也会让测试集失去独立性。','哪一项更能检验策略能否泛化？',['只展示表现最好的一年','使用未参与调参的数据'],1],
'交易成本':['胜率之外，还有成本','净结果 = 返还 − 投入 − 费用。即使每次交易毛收益为正，累计费用也可能使净收益为负。','投入500，费用5，返还525，净结果是？',['+20','+25'],0],
'未来数据泄漏':['不能偷看明天的答案','如果今天决策用到了明天才知道的收盘价，回测就偷看了未来。需要逐字段核对数据发布时间和可用时间。','今天的决策能用什么？',['明日公布的财报','今天已经公布的数据'],1],
'资金占用':['给选择权留一点空间','投入比例描述有多少预算暂时被占用。备用金可以应对其他任务；投入更多不代表资金管理更好。','预算10000，投入3000，投入比例是？',['30%','70%'],0],
'概率与结果':['一次赢，并不能证明方法对','已知概率只描述重复试验的分布。一次结果既包含决策也包含随机性。应把过程证据与盈亏分开。','一轮盈利意味着？',['已经证明真实投资能力','只观察到一个模拟结果'],1]
};
function lesson(concept){concept=concept||s?.event?.concept||'交易成本';const l=lessons[concept];open('微课堂 · '+concept,`<article class="lesson"><div class="eyebrow">随时返回 · 不改变事件与概率</div><h3>${l[0]}</h3><p>${l[1]}</p><label for="sim">试一试：投入金额 <b id="simvalue">500</b> 币</label><input id="sim" type="range" min="100" max="2000" step="100" value="500"><div class="facts" id="simout">返还 525 − 投入 500 − 费用 5 = 净结果 +20</div><p>小练习：${l[2]}</p><div class="choices">${l[3].map((a,i)=>`<button data-do="quiz" data-concept="${concept}" data-id="${i}">${a}</button>`).join('')}</div><p id="quizfeedback" role="status"></p><div class="actions" style="margin-top:20px"><button class="primary" data-do="close">返回${s?'董事会':'开局'}</button><button data-do="lessonMenu">更多概念</button>${PandaAI.enabled?`<button data-do="aiLesson" data-concept="${concept}">让伙伴针对这次决定讲解</button>`:''}</div><div id="aiLessonText"></div></article>`);$('#sim').oninput=e=>{const a=Number(e.target.value);$('#simvalue').textContent=a;$('#simout').textContent=`返还 ${Math.floor(a*1.05)} − 投入 ${a} − 费用 ${Math.ceil(a*.01)} = 净结果 +${Math.floor(a*1.05)-a-Math.ceil(a*.01)}`};if(s&&!s.lessons.includes(concept)){s.lessons.push(concept);save();}}
function resources(){const labels={'探索基础':['基础概念实验室','回撤'],'验证交易想法':['策略验证工作单','样本外验证'],'编程研究':['数据时间戳检查','未来数据泄漏'],'工具实践':['预算模拟器','资金占用']};const [title,concept]=labels[s.goal]||labels['探索基础'];return `<div class="grid2"><div class="panel"><span class="badge">内置演示资源 · 免费</span><h3 style="margin-top:12px">${title}</h3><p class="muted">因为你选择了「${s.goal}」。前置条件：无；形式：讲解 + 小实验；无需平台权限。</p><button data-do="resource" data-concept="${concept}">开始学习 →</button><button class="quiet small" data-do="feedback" data-id="${title}">${s.resourceFeedback.includes(title)?'已记为不适合':'不适合我'}</button></div><div class="panel"><span class="badge">内置演示资源 · 免费</span><h3 style="margin-top:12px">净收益与成本工作台</h3><p class="muted">本局所有行动都有成本。${s.lessons.includes('交易成本')?'你已学过，可再次巩固。':'这个练习可补齐未验证的成本概念。'}前置条件：无。</p><button data-do="resource" data-concept="交易成本">打开工作台 →</button></div></div><small>Panda 平台目录尚未接入。这里提供可立即使用的内置学习资源，没有虚构真实课程链接。</small>`}
function summary(){app.innerHTML=`<div class="shell">${header()}<main class="summary"><div class="eyebrow">第 4 天 · 财报已确认</div><h1>你的策略画像</h1><p class="muted">9 次选择加上产业建设，一起算出四种属性占比。</p><div class="numbers"><div><small>最后余额</small><strong>${s.balance.toLocaleString()}</strong></div><div><small>完成进度</small><strong>3 天 / 9 轮</strong></div><div><small>建成产业</small><strong>${s.city?.districts?.length||0} / 4</strong></div></div><div class="panel"><h2>最终画像</h2>${analystBody()}<details><summary>看原始记录</summary>${profileBody()}</details></div><div class="actions" style="margin-top:25px"><button class="primary" data-do="restart">再玩一局</button><button data-do="ledger">看账本</button><button data-do="bonds">看四个角色</button><button class="quiet" data-do="export">导出记录</button></div></main>${foot()}</div>`;save();}
function cgHTML(){return s.cg==='ready'?'<div class="cg"><small>MOCK CG · 剧情演出</small><br><b>✦ 海风之上，新的盟约 ✦</b><p>星光装饰已解锁。每个有依据的决定，都让董事会更了解你。</p></div>':s.cg==='generating'?'<p class="muted">剧情画面准备中… <button class="small" data-do="cancelCG">取消</button></p>':s.cg==='cancelled'?'<small>剧情画面已取消，结算不受影响。</small>':'<button class="small quiet" data-do="cg">展开本夜剧情 CG（Mock）</button>';}
function cg(){s.cg='generating';save();render();const token=++cgToken,id=s.event.id;setTimeout(()=>{if(token!==cgToken||s?.event?.id!==id||s.phase!=='result')return;s.cg='ready';save();render();},700);}
function settings(){open('事务所设置',`<label for="rename">昵称（最多12字）</label><input id="rename" maxlength="12" value="${esc(s.name)}"><button class="small" data-do="rename">修改称呼</button><div class="notice">${s.save?'当前在浏览器本地自动保存':'当前临时体验，关闭或刷新后不保留本局'}。可以导出 JSON 账本备份。未接入真实 AI / Panda API。</div><div class="actions"><button data-do="toggleSave">${s.save?'停止保存并删除本地存档':'开启本地保存'}</button><button data-do="export">导出本局记录</button><button data-do="aiOptions">剧情 AI 设置</button><button data-do="restart">重开新局</button><button data-do="clear">清除本地进度与画像</button></div>`)}
app.addEventListener('click',event=>handle(event));modal.addEventListener('click',event=>handle(event));
function handle(event){const b=event.target.closest('[data-do]');if(!b||b.disabled||!b.isConnected)return;const d=b.dataset;if(s?.tutorial==='build'&&d.do==='district'&&d.id!==s.ledger.at(-1)?.attribute)return;call(()=>{switch(d.do){case'startDay':G.startDay(s);save();render();break;case'finalProfile':s.phase='summary';save();render();break;case'dismissFeedback':s.city.feedback=null;save();city();break;case'aiProfile':remoteProfile();break;case'aiLesson':remoteLesson(d.concept);break;case'poolReveal':poolReveal();break;case'aiOptions':aiOptions();break;case'aiEnable':PandaAI.enabled=true;close();toast('已开启剧情AI；本局匿名游戏信息会发送到服务端。');break;case'aiDisable':PandaAI.enabled=false;PandaAI.cancel();close();toast('已切回本地剧情。');break;case'askName':askName();break;case'cardHall':cardHall();break;case'drawPool':drawPool(d.id);break;case'warehouse':warehouse();break;case'records':open('董事长手账','<div class="actions"><button data-do="ledger">事件账本</button><button data-do="cityLedger">城市账本</button><button data-do="profile">过程证据</button><button data-do="lessonMenu">微课堂</button><button data-do="bonds">伙伴档案</button></div>');break;case'tutorialReward':if(s.tutorial!=='reward')break;s.city.materials.momentum++;s.city.materials.lowvol++;s.tutorial='build';s.view='city';save();render();toast('收到动量木材与低波钢材，去建造吧。');break;case'finishTutorial':s.tutorial='done';s.view='city';if(s.phase==='result')G.next(s);save();render();break;case'tagStatus':if(G.people.some(p=>p.id===d.id))G.correct(s,d.id,d.value);s.analystCorrections||={};s.analystCorrections[d.id]={...(s.analystCorrections[d.id]||{}),status:d.value};s.profileVersion++;save();summary();break;case'tagEdit':{const l=currentAnalysis().labels.find(l=>l.id===d.id);open('修改这条标签',`<label for="tagText">请用自己的话描述（最多80字）</label><input id="tagText" maxlength="80" value="${esc(l.edited||l.text)}"><button class="primary" data-do="tagSave" data-id="${d.id}">保存我的描述</button>`);break;}case'tagSave':{const text=$('#tagText').value.trim();if(!text)throw Error('描述不能为空');s.analystCorrections||={};s.analystCorrections[d.id]={status:'confirmed',text};s.profileVersion++;save();modal.close();summary();break;}case'template':{const c=ProfileAnalyst.catalog.find(c=>c.id===d.id&&c.status==='active');if(!c)throw Error('资源不可用');open(c.title,`<span class="badge">内置演示 / ${c.kind}</span><p style="margin-top:15px">${c.description}</p><div class="notice">不是实际资金策略建议。所需数据：自备或合成研究样本；研究时必须自行定义费用、样本区间和验证基准。本原型不连接真实账户。</div><button class="primary" data-do="resource" data-concept="${c.concept}">进入配套微课堂</button>`);break;}case'city':PandaAI.cancel();clearTimeout(drawTimer);if(s.phase==='drawing')s.phase='ready';s.view='city';save();render();break;case'board':modal.close();s.view='board';save();render();break;case'pool':toast(GameCity.draw(s,d.id));save();city();break;case'district':district(d.id);break;case'buildCity':{const chosen=[...modal.querySelectorAll('input[name=factor]:checked')].map(x=>x.value);GameCity.build(s,d.id,chosen,Number($('#cityBudget').value));if(s.tutorial==='build')s.tutorial='finish';save();modal.close();city();toast('区域蓝图已落地，等待第一段行情。');break;}case'cityBudget':{const ids=[...modal.querySelectorAll('input[name=factor]:checked')].map(x=>x.value);GameCity.refit(s,d.id,ids,Number($('#cityBudget').value));save();modal.close();city();break;}case'cycle':{const a=GameCity.draft(s);s.city.pending=a;open('推进一段合成行情',`<p>本周期所有区域将按当前材料与预算同时模拟，立即平仓。参数现在锁定。</p><div class="numbers"><div><small>总投入</small><strong>${a.amount}</strong></div><div><small>维护与换手费</small><strong>${a.fees}</strong></div><div><small>保留现金</small><strong>${s.balance-a.amount-a.fees}</strong></div></div><p class="notice">教学规则 city-1.0：合成市场变动在 −8% 至 +8%；不同策略和材料改变暴露。净结果可能为负；组合毛收益界限约 −12% 至 +12%，再扣上述费用。没有真实行情或 Panda 回测。</p><button class="primary" data-do="confirmCycle">确认推进周期</button><button data-do="close">取消</button>`);break;}case'confirmCycle':{if(!s.city.pending)break;const a=s.city.pending;GameCity.settle(s,a);save();modal.close();city();toast('行情已结算，城区建设与稳定性已更新。');break;}case'cityLedger':cityLedger();break;case'close':close();break;case'continue':s=migrateStrategies(JSON.parse(JSON.stringify(saved)));s.tutorial||='done';if(s.phase==='drawing')s.phase='ready';if(s.cg==='generating')s.cg='cancelled';s.draft=null;render();break;case'draw':if(s.phase!=='ready')break;if(!s.event)G.draw(s);s.phase='drawing';save();render();drawTimer=setTimeout(reveal,window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?40:2400);break;case'reveal':reveal();break;case'cancelDraw':clearTimeout(drawTimer);s.phase='ready';save();render();break;case'npc':PandaAI.cancel();s.npc=Number(d.id);save();render();break;case'ask':ask(d.kind,true);break;case'choose':confirmAction(d.id);break;case'confirm':{if(!s.draft)break;const a={...s.draft,reason:$('#reason').value};b.disabled=true;G.settle(s,a);const linked=GameCity.init(s),attribute=s.ledger.at(-1)?.attribute;if(attribute&&!linked.blueprints.includes(attribute))linked.blueprints.push(attribute);if(s.tutorial==='decision')s.tutorial='reward';say(a.amount?`董事长，${a.amount} 币试验已经落账。下一夜，我们可以回看这次假设是否得到检验；一次输赢还不说明方法。`:a.report?`董事长，报告已经归档。时间戳、独立样本和完整费用，是我们下一次讨论的起点。`:`董事长，这一夜你保留了现金。选择观察也有它的理由，我会记住你对这次情境的解释。`);if(s.round===G.CONFIG.rounds-1){G.next(s);save();modal.close();render();toast('第三天完成，已结算；请先查看第 4 天最终财报。');}else{save();modal.close();render();toast('决策已记录，故事继续。');}break;}case'next':PandaAI.cancel();cgToken++;G.next(s);save();render();break;case'ledger':ledger();break;case'replay':{const l=s.ledger[Number(d.id)],r=G.replay(l.event,l.proposal);toast(r.delta===l.delta?'核验一致：净变化 '+r.delta+' 币':'核验异常，请导出账本');break;}case'bonds':bonds();break;case'partnerDetail':partnerDetail(Number(d.id));break;case'profile':open('本局画像证据',profileBody());break;case'correct':G.correct(s,d.id,d.value);s.analystCorrections||={};s.analystCorrections[d.id]={...(s.analystCorrections[d.id]||{}),status:d.value};save();if(s.phase==='summary'&&!modal.open)summary();else open('本局画像证据',profileBody());toast('已更新画像；拒绝的观察不会自动重新启用');break;case'goal':s.goal=$('#profileGoal').value;s.profileVersion++;save();if(s.phase==='summary')summary();toast('学习目标已更新，推荐使用新目标');break;case'lesson':case'introLesson':lesson();break;case'lessonMenu':open('选择一间微课堂',Object.keys(lessons).map(c=>`<p><button data-do="resource" data-concept="${c}">${c} →</button></p>`).join(''));break;case'resource':lesson(d.concept);break;case'quiz':{const yes=Number(d.id)===lessons[d.concept][4];$('#quizfeedback').textContent=yes?'答对了。你完成了一次学习后练习；还不能据此判断迁移能力。':'再想想。上面的讲解可以帮助你核对，不扣分。';if(s&&yes&&!s.quiz.includes(d.concept)){s.quiz.push(d.concept);s.xp+=10;G.evidence(s,'knowledge',d.concept+'练习答对','task_result','after_learning',true);save();}break;}case'cg':cg();break;case'cancelCG':cgToken++;s.cg='cancelled';save();render();break;case'settings':settings();break;case'rename':s.name=($('#rename').value.trim().slice(0,12)||'玩家').replace(/总+$/,'')||'玩家';save();close();render();break;case'toggleSave':s.save=!s.save;if(s.save)save();else{localStorage.removeItem(KEY);saved=null;}settings();break;case'restart':open('开启新一局？','<p>本局会被新局替换。若想保留记录，可以先导出。</p><div class="actions"><button data-do="export">导出本局</button><button class="primary" data-do="new">确认重开</button><button data-do="close">取消</button></div>');break;case'new':PandaAI.cancel();cgToken++;clearTimeout(drawTimer);localStorage.removeItem(KEY);saved=null;modal.close();intro();break;case'clear':open('清除本地记录？','<p>删除此游戏在浏览器中的进度与画像；该操作不能撤回。已导出的文件需要你自行删除。</p><button class="primary" data-do="clearYes">确认清除</button><button data-do="close">取消</button>');break;case'clearYes':PandaAI.cancel();clearTimeout(drawTimer);clearTimeout(poolTimer);cgToken++;localStorage.removeItem(KEY);saved=null;s=null;modal.close();intro();toast('本地进度与画像已清除');break;case'feedback':if(!s.resourceFeedback.includes(d.id))s.resourceFeedback.push(d.id);save();summary();toast('已记录反馈，可修改学习目标获得不同推荐');break;case'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'}));a.href=url;a.download='量化董事会-本局记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}});}
function currentAnalysis(){const a=JSON.parse(JSON.stringify(s.aiProfile||ProfileAnalyst.analyze(s)));for(const l of a.labels){const c=s.analystCorrections?.[l.id]||s.corrections?.[l.id];if(c){l.status=typeof c==='string'?c:c.status;l.edited=c.text||null;}}return a;}
function decisionTrace(){const types={trend:{name:'趋势型',role:'趋势交易员·赤霄',score:0},value:{name:'价值型',role:'价值买手·知夏',score:0},defense:{name:'防守型',role:'现金守门员·凛川',score:0},research:{name:'研究型',role:'研究分析师·星澜',score:0}};for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(types[e.value])types[e.value].score++;const total=Object.values(types).reduce((n,x)=>n+x.score,0)||1,ranked=Object.values(types).sort((a,b)=>b.score-a.score),top=ranked[0],person=G.people.find(p=>p.name===top.role),raw=Object.values(types).map(x=>x.score/total*100),floors=raw.map(Math.floor),left=100-floors.reduce((a,b)=>a+b,0),order=raw.map((x,i)=>({i,r:x-floors[i]})).sort((a,b)=>b.r-a.r);for(let i=0;i<left;i++)floors[order[i%order.length].i]++;Object.values(types).forEach((x,i)=>x.percent=floors[i]);return `<section class="decision-map"><div class="result-role">${art(person,'result-portrait')}<div><small>你的主角色</small><h2>${top.role}</h2><h3>${top.name} · ${top.percent}%</h3><p>${esc(person.hint)}</p></div></div><div class="strategy-grid">${Object.values(types).map(x=>`<span class="${x===top?'top':''}"><b>${x.percent}%</b>${x.name}<small>${x.score} 点 · ${x.role}</small></span>`).join('')}</div><p class="muted">百分比合计 100%。每轮选择 +1，首次建设对应产业也 +1。</p></section>`;}
function strategyGuide(){const counts={trend:0,value:0,defense:0,research:0};for(const e of s.evidence.filter(e=>e.dimension==='attribute'))if(e.value in counts)counts[e.value]++;const top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0][0],humor={trend:'你的手比新闻推送还快：看到方向就想上车，但记得车也会掉头。',value:'你像逛打折区的董事长：便宜会心动，不过先确认不是“清仓甩卖”。',defense:'你是董事会的现金保安：别人冲浪，你先检查救生衣。',research:'你是董事会的问号制造机：不先把依据问明白，钱就别想出门。'}[top];const guides=[{id:'trend',name:'趋势策略',plain:'已经涨出方向再跟随，常见做法是均线、突破和动量；反转时要及时退出。',match:'匹配：动量因子、均线、突破、ATR 止损。',url:'https://www.pandaaiquant.com/docs/strategy',cta:'看策略开发与趋势模板'},{id:'value',name:'价值策略',plain:'找价格相对便宜、基本面还能撑住的标的，分批验证，不把“跌了”自动当成“便宜”。',match:'匹配：PB、PE、ROE、现金流等财务因子。',url:'https://www.pandaaiquant.com/docs/factor-library',cta:'看 PandaAI 因子库'},{id:'defense',name:'防守策略',plain:'少押、留现金、控制回撤和波动，目标是先活下来，再等下一次机会。',match:'匹配：低波动、仓位控制、费用与风险检查。',url:'https://www.pandaaiquant.com/docs/strategy',cta:'看风控与策略闭环'},{id:'research',name:'研究策略',plain:'先验证数据、样本和成本，再决定是否投入，重点防止未来数据泄漏和漂亮曲线骗人。',match:'匹配：因子分析、IC、样本外验证、量价研究。',url:'https://www.pandaaiquant.com/docs/quantfactor-center',cta:'去量化因子中心'}];return `<section class="strategy-guide"><div class="humor-profile"><b>董事会吐槽式鉴定</b><p>${humor}</p></div><h2>四种策略到底在干什么？</h2>${guides.map(g=>`<article class="strategy-explain ${g.id===top?'best':''}"><span class="badge">${g.id===top?'最匹配':'可搭配'} · ${counts[g.id]} 点</span><h3>${g.name}</h3><p>${g.plain}</p><small>${g.match}</small><a href="${g.url}" target="_blank" rel="noopener noreferrer">${g.cta} →</a></article>`).join('')}<a class="course-cta" href="https://www.pandaaiquant.com/learninghub/newcourse" target="_blank" rel="noopener noreferrer">还看不懂？去量变学院系统学 →</a></section>`;}
function analystBody(){const a=currentAnalysis();return `<div class="notice">${a.mode==='ai'?'DeepSeek 生成的候选画像 · 置信度为未校准证据等级，需你确认。':'规则模拟画像 / AI 未接入。'}${PandaAI.enabled?'<button class="small" data-do="aiProfile">生成 AI 复盘</button>':''}</div><p>${esc(a.narrative)}</p>${decisionTrace()}${strategyGuide()}${a.labels.map(l=>`<div class="claim"><h3>${esc(l.edited||l.text)} <span class="badge">${statusNames[l.status]}</span></h3><small>${esc(l.context)}${l.confidence?' · 证据等级 '+esc(l.confidence):''}</small><small>证据：${l.evidence_ids.join('、')} · ${l.edited?'你修改的自述':'规则模拟候选'}</small><div class="actions"><button class="small" data-do="tagStatus" data-id="${l.id}" data-value="confirmed">确认</button><button class="small" data-do="tagStatus" data-id="${l.id}" data-value="rejected">拒绝</button><button class="small" data-do="tagEdit" data-id="${l.id}">修改描述</button></div></div>`).join('')||'<p>标签未知：缺少足够行为证据。</p>'}<h3>匹配的策略学习模板与课程</h3>${a.recommendations.map(r=>{const c=ProfileAnalyst.catalog.find(c=>c.id===r.resource_id);return `<div class="claim"><span class="badge">内置演示 · ${c.kind} · ${c.fee}</span><h3>${c.title}</h3><p class="muted">${esc(r.reason)}</p><small>目录 ID：${c.id} · 先修：无 · 权限：本地开放 · 仅供模拟研究</small><button data-do="template" data-id="${c.id}">打开资源 →</button></div>`}).join('')}`}
function city(){const c=GameCity.init(s),t=s.tutorial&&s.tutorial!=='done',target=s.ledger.at(-1)?.attribute||'trend',targetBlueprint=GameCity.blueprints.find(b=>b.id===target),feedback=c.feedback?`<aside class="city-feedback"><b>${esc(c.feedback.title)}</b><p>${esc(c.feedback.text)}</p><button class="small" data-do="dismissFeedback">知道了</button></aside>`:'';app.innerHTML=`<main class="game city-game ${s.tutorial==='build'?'tutorial-build tutorial-'+target:''}">${world(!t||s.tutorial==='build')}${hud()}${s.tutorial==='build'?`<div class="tutorial-banner">你刚才选了${targetBlueprint.strategy}决策。现在建对应产业。<span>↓</span></div><div class="tutorial-objective">建${targetBlueprint.name} · ${targetBlueprint.strategy} +1</div>`:s.tutorial==='finish'?`${character()}${speech(`${targetBlueprint.name}建好了。<br>${esc(c.feedback?.text||targetBlueprint.strategy+' +1。')}`,'<button class="primary" data-do="finishTutorial">继续玩 →</button>')}`:`<div class="island-name">量化董事会<small>${c.districts.length} / 4 个产业</small></div><button class="mail-float" data-do="board" aria-label="打开市场事件">${CityArt.icon('cards')}<i></i></button>${dock()}${feedback}`}<div class="ambient-leaf leaf1"></div><div class="ambient-leaf leaf2"></div>${foot()}</main>`;save();}
function cardHall(){const c=GameCity.init(s),day=GameCity.gameDay(s),strategy=c.drawn['strategy-day-'+day],factor=c.drawn['factor-day-'+day],types=GameCity.blueprints.map(b=>`<span><b>${b.name}</b><small>${b.partner}</small></span>`).join(''),materials=GameCity.factors.map(f=>`<span><b>${f.name}</b><small>${f.label}</small></span>`).join('');open('第 '+day+' 天策略补给站',`<p class="muted">每天完成 3 次市场决策；蓝图卡和材料卡各抽 1 张。四类卡与四位 SR 伙伴一一对应。</p><div class="strategy-link-grid">${types}</div><div class="poolselection"><button class="pool-card" data-do="board"><span>✦</span><b>市场决策</b><small>${s.round%3}/3 已完成</small></button><button class="pool-card blueprint-pool" data-do="drawPool" data-id="strategy" ${strategy?'disabled':''}><span>${CityArt.icon('blueprint')}</span><b>抽城区蓝图</b><small>${strategy?'今天抽过了':'趋势 / 价值 / 防守 / 研究'}</small></button><button class="pool-card materials-pool" data-do="drawPool" data-id="factor" ${factor?'disabled':''}><span>${CityArt.icon('wood')}</span><b>抽因子材料</b><small>${factor?'今天抽过了':'四个产业各有专属材料'}</small></button></div><details><summary>查看四类材料</summary><div class="strategy-link-grid materials">${materials}</div></details>`)}
function drawPool(pool){if(poolLoot)return;const item=GameCity.draw(s,pool),rarity=s.city.draws.at(-1).rarity;save();poolLoot={pool,item,rarity};open('补给抵港',`<div class="pool-spin-stage"><button class="sealedcard poolspin ${pool} rarity-${rarity.toLowerCase()}" data-do="poolReveal"><span class="rarity-badge">${rarity}</span><span class="seal">✦</span><b>${pool==='strategy'?'城区蓝图':'因子材料'}</b><small>点击跳过演出</small></button></div>`);poolTimer=setTimeout(poolReveal,window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?40:2400);}
function poolReveal(){if(!poolLoot)return;clearTimeout(poolTimer);const {pool,item,rarity}=poolLoot;poolLoot=null;const clean=item.replace(/ × 2$/,''),bp=GameCity.blueprints.find(x=>item.includes(x.name)),factor=GameCity.factors.find(x=>clean===x.name),explain=bp?`${bp.strategy}产业：${bp.description} 建成后对应属性 +1。`:factor?`${factor.label}：${factor.description} 建筑配置时会消耗它。`:'四个产业蓝图已经集齐，所以改送一份补充材料。';open(rarity+' 抽到了',`<div class="loot-reveal rarity-${rarity.toLowerCase()}"><div class="loot-icon">${CityArt.icon(pool==='strategy'?'blueprint':'wood')}</div><h3>${item}</h3><p>${esc(explain)}</p><small>已放进仓库 · 今天不能再抽同类卡</small><button class="primary" data-do="close">收下</button></div>`)}
function warehouse(){const c=GameCity.init(s);open('因子知识库',GameCity.factors.map(f=>`<div class="material-row"><div class="material-icon"><b>${f.difficulty}</b></div><div><b>${f.name} × ${c.materials[f.id]}</b><small>${f.description}</small><a class="concept-help" href="https://www.pandaaiquant.com/learninghub/newcourse" target="_blank" rel="noopener noreferrer" title="去课程中心学习${f.concept}">? ${f.concept}</a></div></div>`).join('')+'<p class="muted">R 是基础概念，SR 是进阶，SSR 需要综合理解。问号会打开 PandaAI 课程中心。</p>')}

function district(id){const c=GameCity.init(s),b=GameCity.blueprints.find(b=>b.id===id),d=c.districts.find(d=>d.id===id);if(!c.blueprints.includes(id))return toast('先从策略蓝图池领取这块地的蓝图。');open(b.name,`<div class="eyebrow">${b.strategy} / 教学策略区域</div><p>${b.description}</p>${d?`<p>建设 ${d.development}%，稳定度 ${d.stability}%。替换材料会返还原材料，消耗新材料。</p>`:'<p class="muted">选择1–2种材料，建设时各消耗1份。首次建设免费；预算只在确认推进周期时投入。</p>'}${GameCity.factors.map(f=>`<label><input type="checkbox" name="factor" value="${f.id}" ${d?.factors.includes(f.id)?'checked':''} ${c.materials[f.id]||d?.factors.includes(f.id)?'':'disabled'}> ${f.name}（仓库${c.materials[f.id]}）<small> · ${f.label}</small></label>`).join('')}<label for="cityBudget">每周期模拟投入（100–5000整数）</label><input id="cityBudget" type="number" min="100" max="5000" step="100" value="${d?.budget||1000}"><div class="notice">所有地区共用董事长账本。每周期先校验总预算与费用，结算后返还本金及模拟结果。毛收益为策略暴露与材料规则计算；费用 = 预算 × 换手费率向上取整。建设不是投资推荐。</div><button class="primary" data-do="${d?'cityBudget':'buildCity'}" data-id="${id}">${d?'保存材料与预算':'确认建设这个区域'}</button>`)}
function cityLedger(){const c=GameCity.init(s);open('城市周期账本',`${c.ledger.map(l=>`<div class="ledgeritem"><b>周期 ${l.cycle+1} · ${l.market.regime} · 市场 ${l.market.basisPoints/100}%</b><br>${l.balanceBefore} → ${l.balanceAfter} 币${l.details.map(d=>`<p>${GameCity.blueprints.find(b=>b.id===d.id).name}：投入 ${d.budget} / 费用 ${d.fee} / 返还 ${d.credit}<br><small>材料 ${d.factors.join(', ')} · 组合毛结果 ${d.bp/100}%</small></p>`).join('')}<small>seed ${l.market.seed} · ${l.rule} · ${l.idempotencyKey}</small></div>`).join('')||'<p>还没有推进周期。先建设一个区域吧。</p>'}<p class="muted">城市和事件共享余额；完整导出记录包含两份只追加账本。</p>`)}
async function aiOptions(){const status=await PandaAI.status();open('智慧角色',`<p>${status.mode==='available'?'服务端 AI 已配置，可以开启。':'AI 尚未配置，当前使用本地剧情。'}</p><p><b>角色语音：${status.voice==='available'?'ElevenLabs 已连接':'未配置'}</b></p><p class="muted">开启后只发送当前合成事件、匿名选择、课堂概念和证据。角色语音开启时会把生成的短对白发送给 ElevenLabs，并产生相应用量。金币与结算仍由本地规则计算。</p>${status.mode==='available'?'<button class="primary" data-do="aiEnable">同意并开启智慧角色</button>':''}<button data-do="aiDisable">使用本地剧情</button>`)}
async function remoteDialogue(text){const eventId=s.event?.id,npc=s.npc,run=s.id;toast('正在听取伙伴的想法…');const result=await PandaAI.request('dialogue',{role:G.people[npc].id,message:text,facts:s.event||{}},run+'-'+Date.now());if(!s||s.id!==run||s.event?.id!==eventId||s.npc!==npc)return;const reply=result?.text||G.parse(s,text).message||'先核对规则，再决定这一步。';say(reply);render();if(result)PandaAI.speak(G.people[npc].id,reply);}
async function remoteEvent(){const id=s.event.id,run=s.id;const result=await PandaAI.request('event',{facts:s.event,role:G.people[s.npc].id},id+'-story');if(result&&s?.id===run&&s.event?.id===id&&s.phase==='event'&&!s.draft){s.event.story=result.story;s.event.title=result.title;s.event.source='DeepSeek 叙事 / 本地锁定规则';save();render();}}
async function remoteLesson(concept){const id=s?.event?.id,run=s?.id;const target=$('#aiLessonText');if(!target)return;target.textContent='伙伴正在整理讲解…';const result=await PandaAI.request('lesson',{concept,facts:s?.event||{},choices:s?.ledger.slice(-2).map(l=>({action:l.actionId,reason:l.proposal.reason}))||[]},(run||'lesson')+'-'+Date.now());if(!target.isConnected||!modal.open||s?.id!==run||s?.event?.id!==id)return;target.innerHTML=result?`<h3>${esc(result.title)}</h3><p>${esc(result.explanation)}</p><small>DeepSeek生成讲解；下方原有练习仍按本地规则判断。</small>`:'暂时没有收到讲解，可继续使用上面的本地课堂。';}
async function remoteProfile(){const run=s.id,v=s.profileVersion;toast('伙伴正在整理本局证据…');const result=await PandaAI.request('profile',{evidence:s.evidence,goal:s.goal,choices:s.ledger.map(l=>({action:l.actionId,reason:l.proposal.reason})),city:s.city?.districts||[]},run+'-profile-'+v);if(!s||s.id!==run||s.profileVersion!==v)return;if(result){try{ProfileAnalyst.validate(result,s);s.aiProfile=result;save();summary();}catch{toast('画像证据校验失败，保留本地结果。');}}else toast('AI暂不可用，保留本地结果。');}
function reveal(){if(s?.phase!=='drawing')return;clearTimeout(drawTimer);s.phase='event';if(!s.event)G.draw(s);if(s.event?.lead){const lead=G.people.findIndex(p=>p.id===s.event.lead);if(lead>=0)s.npc=lead;}if(s.tutorial==='draw')s.tutorial='decision';save();render();if(PandaAI.enabled)remoteEvent();}
window.addEventListener('storage',e=>{if(e.key===KEY){toast('另一个标签页修改了存档。为避免冲突，本页改为临时体验。');if(s)s.save=false;}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button][data-do]')){e.preventDefault();handle({target:e.target});}});
window.addEventListener('offline',()=>toast('离线可继续：规则、课堂与存档均在本机运行。'));
if(saved){s=migrateStrategies(JSON.parse(JSON.stringify(saved)));s.tutorial||='done';if(s.phase==='drawing')s.phase='ready';s.draft=null;if(s.city)s.city.pending=null;if(s.cg==='generating')s.cg='cancelled';render();}else intro();
})();
